actions.script:
def fmt = { v -> ec.l10n.format((v ?: 0) as BigDecimal, "#,##,##0") }
def confWord = { p -> p == null ? "Building up" : (p >= 75 ? "Strong" : (p >= 60 ? "Good" : (p >= 45 ? "Fair" : "Early estimate"))) }
def trendWord = { t -> t == "growing" ? "Going up" : (t == "softening" ? "Slowing down" : "Holding steady") }
def driverWord = { d ->
    if (!d) return "—"
    def up = d.toString().contains("rising")
    if (d.toString().contains("footfall")) return up ? "More customers coming in" : "Fewer customers coming in"
    return up ? "Customers spending more each visit" : "Customers spending a little less"
}
// ZE-SALES-026 f/u (SL-089): safe defaults so the widgets never NPE when there's no org / no forecast.
trendNice = "—"; driverNice = "—"; perDay = 0; hasData = false; catChartHtml = ""; heroChartHtml = ""
confNice = confWord(null); confColor = "grey"
trendIco = "trending_flat"; trendBadgeColor = "grey"
if (fc == null) {
    plain = noOrg ? "Choose your business from the organization picker at the top of the page to see its sales forecast."
                  : "We need a couple of weeks of sales before we can predict reliably. Keep billing through the POS and check back soon."
    leadLine = plain
} else {
    trendNice = trendWord(fc.trendLabel)
    trendIco = (fc.trendLabel == 'growing') ? 'trending_up' : (fc.trendLabel == 'softening' ? 'trending_down' : 'trending_flat')
    trendBadgeColor = (fc.trendLabel == 'growing') ? 'green' : (fc.trendLabel == 'softening' ? 'red' : 'grey')
    driverNice = driverWord(fc.primaryDriver)
    confNice = confWord(fc.confidencePct)
    hasData = (fc.confidencePct != null)
    confColor = (fc.confidencePct != null && fc.confidencePct >= 60) ? "success" : (fc.confidencePct != null && fc.confidencePct >= 45 ? "warning" : "grey")
    perDay = (fc.projectedNext7 != null) ? (fc.projectedNext7 / 7.0) : 0
    // plain-words summary + a single glance-able lead line (replaces the dense paragraph)
    if (hasData) {
        plain = "Over the next 7 days you're likely to sell about " + sym + fmt(fc.projectedNext7) +
            " — roughly " + sym + fmt(perDay) + " a day. Sales are " + trendNice.toLowerCase() +
            ", and " + (fc.peakDay ?: "the weekend") + " is usually your busiest day. " +
            "Expect around " + fmt(fc.next7Traffic) + " customers spending about " + sym + fmt(fc.next7Aov) + " each. " +
            "The main change right now: " + driverNice.toLowerCase() + ". " +
            "How sure are we? " + confNice + " — and this gets sharper every day as more sales come in."
        leadLine = "You're on track to sell about " + sym + fmt(fc.projectedNext7) + " this week — sales are " +
            trendNice.toLowerCase() + ", and " + driverNice.substring(0,1).toLowerCase() + driverNice.substring(1) + "."
    } else {
        plain = "We need a couple of weeks of sales before we can predict reliably. Keep billing through the POS and check back soon."
        leadLine = plain
    }
    catList.each { it.dirNice = trendWord(it.trend); it.relWord = confWord(it.confidencePct) }
    catList = catList.sort { -((it.projectedNext7 ?: 0) as BigDecimal) }
    def _maxCat = catList ? (catList.collect { (it.projectedNext7 ?: 0) as BigDecimal }.max()) : null
    catList.each { c ->
        def v = (c.projectedNext7 ?: 0) as BigDecimal
        c.barPct = (_maxCat != null && _maxCat > 0) ? (v * 100 / _maxCat).setScale(1, java.math.RoundingMode.HALF_UP) : (0 as BigDecimal)
    }
    // Build the horizontal bar chart as raw HTML — Moqui containers put `style` into `class`, so a
    // proportional-width bar needs real inline styles, which only render-mode HTML provides.
    def _esc = { s -> (s ?: '').toString().replace('&','&amp;').replace('<','&lt;').replace('>','&gt;') }
    // categorical palette by group (mockup): primary, blue, red, green, orange, primary-dark
    def _palette = ['#7C3AED','#3B82F6','#EF4444','#10B981','#F59E0B','#6D28D9']
    def _dir = { t -> (t == 'growing') ? ['#0E9F6E','&#8599; Going up'] : (t == 'softening' ? ['#DC2626','&#8600; Slowing down'] : ['#6B7280','&#8212; Holding steady']) }
    def _b = new StringBuilder()
    _b.append('<div class="zsf-category-scroll"><div class="zsf-category-table" style="font-size:0.9rem;">')
    _b.append('<div style="display:flex;align-items:center;gap:12px;padding-bottom:6px;font-size:0.68rem;text-transform:uppercase;letter-spacing:.04em;color:#9a9aa8;font-weight:700;">')
    _b.append('<div style="width:24%;">Group</div><div style="flex:1;">Share of next 7 days</div><div style="width:96px;text-align:right;">Next 7 days</div><div style="width:64px;text-align:right;">Per day</div><div style="width:132px;text-align:center;">Direction</div></div>')
    catList.eachWithIndex { c, i ->
        def col = _palette[i % _palette.size()]
        def dd = _dir(c.trend)
        _b.append('<div style="display:flex;align-items:center;gap:12px;padding:9px 0;border-bottom:1px solid rgba(128,128,128,0.14);">')
        _b.append('<div style="width:24%;font-weight:600;">' + _esc(c.category) + '</div>')
        _b.append('<div style="flex:1;background:rgba(128,128,140,0.16);border-radius:9999px;height:9px;overflow:hidden;"><div style="width:' + (c.barPct ?: 0) + '%;min-width:2px;background:' + col + ';height:9px;border-radius:9999px;"></div></div>')
        _b.append('<div style="width:96px;text-align:right;font-weight:700;">' + sym + fmt(c.projectedNext7) + '</div>')
        _b.append('<div style="width:64px;text-align:right;color:#9a9aa8;">' + sym + fmt(c.perDay) + '</div>')
        _b.append('<div style="width:132px;text-align:center;font-size:0.82rem;font-weight:600;color:' + dd[0] + ';">' + dd[1] + '</div>')
        _b.append('</div>')
    }
    _b.append('</div></div>')
    catChartHtml = catList ? _b.toString() : '<p class="zsf-empty">No product-group forecast is available yet.</p>'
    // hero mini 7-day trend chart: last up-to-7 daily actuals as ascending --primary bars
    def _hist7 = histList.findAll { it.actualAmount != null }.take(7).reverse()
    if (_hist7.size() >= 2) {
        def _hmax = _hist7.collect { (it.actualAmount ?: 0) as BigDecimal }.max()
        def _hb = new StringBuilder()
        if (_hmax > 0) {
            _hb.append('<div class="zsf-chart" role="img" aria-label="Sales recorded over the last seven days"><div class="zsf-chart-bars">')
            _hist7.each { h ->
                def v = (h.actualAmount ?: 0) as BigDecimal
                def pct = (v * 100 / _hmax).setScale(0, java.math.RoundingMode.HALF_UP)
                _hb.append('<div class="zsf-chart-col"><span class="zsf-chart-bar" style="height:' + pct + '%"></span></div>')
            }
            _hb.append('</div></div>')
        } else {
            _hb.append('<div class="zsf-chart-empty">No sales recorded in the last 7 days</div>')
        }
        _hb.append('<div class="zsf-chart-caption">Last 7 days</div>')
        heroChartHtml = _hb.toString()
    } else {
        heroChartHtml = '<div class="zsf-chart-empty">Recent sales history is not available yet</div>'
    }
}
